import { DirectionProvider } from "@/registry/erbium/ui/direction";
import {
  NumberField,
  NumberFieldDecrement,
  NumberFieldGroup,
  NumberFieldIncrement,
  NumberFieldInput,
} from "@/registry/erbium/ui/number-field";

const Example = () => (
  <DirectionProvider direction="rtl">
    <div dir="rtl" className="w-48">
      <NumberField defaultValue={98_765} locale="ar-EG">
        <NumberFieldGroup>
          <NumberFieldDecrement />
          <NumberFieldInput aria-label="الكمية" />
          <NumberFieldIncrement />
        </NumberFieldGroup>
      </NumberField>
    </div>
  </DirectionProvider>
);

export default Example;
